1	#!/usr/bin/env node
2	/**
3	 * ─── INTENÇÃO (certidão de nascimento) ───────────────────────────────────────
4	 * POR QUE EXISTE (auditoria fria do kit, 2026-09-10, issue #11): uma linha em `lib/guard-doctrine.mjs`
5	 *   (`ehEntrypoint` devolvendo false) silenciava os 5 guards — saída vazia, exit 0 — e
6	 *   `guards:selftest`, `full-check` e o job do CI (`node guard --self-test || exit 1`) saíam VERDES.
7	 *   É o "guard mudo" que a própria doutrina cita como incidente de origem, reproduzido no kit.
8	 *   O erro de desenho: cobrar exit code sem cobrar EVIDÊNCIA de que o self-test rodou.
9	 *
10	 * O QUE FAZ: roda cada guard com `--self-test` como processo filho e exige a linha
11	 *   `SELF-TEST OK — N/N casos` com N > 0 na saída. Saída vazia, linha ausente, N = 0 ou exit ≠ 0 =
12	 *   vermelho, com o nome do guard. Antes disso, roda os casos das três funções da doutrina
13	 *   (`ehEntrypoint`, `selfTestPedido`, `relatarSelfTest`) no próprio processo. Também roda, com a MESMA
14	 *   doutrina, todo self-test de COMANDO (não guard) que more fora de `scripts/guards/` — lista em
15	 *   `SELFTESTS_FORA_DE_GUARDS` (`./guards-esperados.mjs`, hoje só `scripts/reservar-numero.mjs`): sem
16	 *   isso, o self-test do comando nunca roda no `full-check`/CI e um guard mudo ali passa batido.
17	 *
18	 * O QUE NUNCA MAIS PODE PASSAR:
19	 *   1. guard que sai 0 sem imprimir `SELF-TEST OK` (M17: ehEntrypoint=false);
20	 *   2. relator que mente (M16: `relatarSelfTest` devolvendo 0 com falhas);
21	 *   3. passthrough do npm (`npm run <guard> -- --self-test`) virando contra-prova (M18);
22	 *   4. o próprio runner aceitando saída vazia.
23	 *
24	 * LIMITE CONHECIDO: confere a FORMA da evidência (a linha), não a verdade de cada caso — essa é dos
25	 *   self-tests de cada guard e da mutação feita pelo auditor.
26	 *
27	 * CONTRA-PROVA: `node scripts/guards/run-selftests.mjs --self-test` — inclui um guard falso mudo e
28	 *   um relator falso.
29	 * ─────────────────────────────────────────────────────────────────────────────
30	 */
31	import { spawnSync } from 'node:child_process';
32	import { readdirSync, mkdtempSync, writeFileSync, rmSync } from 'node:fs';
33	import { join, dirname } from 'node:path';
34	import { fileURLToPath } from 'node:url';
35	import { tmpdir } from 'node:os';
36	import { ehEntrypoint, selfTestPedido, relatarSelfTest, mesmoArquivo } from '../lib/guard-doctrine.mjs';
37	import { GUARDS_ESPERADOS, NAO_SAO_GUARDS, SELFTESTS_FORA_DE_GUARDS } from './guards-esperados.mjs';
38	
39	const NOME = 'run-selftests';
40	// RUN_SELFTESTS_DIR existe SÓ para o self-test do próprio runner apontar para uma pasta vazia (prova do R1).
41	const AQUI = process.env.RUN_SELFTESTS_DIR || dirname(fileURLToPath(import.meta.url));
42	// PASTA_MAE nunca muda com RUN_SELFTESTS_DIR (esse env só finge uma pasta de GUARDS vazia/fake pro
43	// self-test deste runner) — é sempre a pasta-mãe REAL de scripts/guards/ (`scripts/` no kit,
44	// `scripts/esteira/` num projeto nascido do bootstrap): SELFTESTS_FORA_DE_GUARDS é relativo A ELA, não
45	// à raiz do repo (repo-relativo quebraria no projeto: scripts/esteira/scripts/... não existe).
46	const PASTA_MAE = dirname(dirname(fileURLToPath(import.meta.url)));
47	const RE_OK = /SELF-TEST OK — (\d+)\/(\d+) casos/;
48	
49	/** FUNÇÃO PURA: julga a saída de um guard rodado com --self-test. */
50	export function julgarSaida({ stdout = '', stderr = '', status = null } = {}) {
51	  const texto = `${stdout}\n${stderr}`;
52	  const m = RE_OK.exec(texto);
53	  if (status !== 0) return { ok: false, motivo: `exit ${status}${/SELF-TEST FALHOU/.test(texto) ? ' (SELF-TEST FALHOU)' : ''}` };
54	  if (!m) return { ok: false, motivo: texto.trim() === '' ? 'saída VAZIA com exit 0 — guard mudo' : 'exit 0 sem a linha "SELF-TEST OK — N/N casos"' };
55	  const n = Number(m[1]), total = Number(m[2]);
56	  if (n === 0 || total === 0 || n !== total) return { ok: false, motivo: `linha diz ${n}/${total}` };
57	  return { ok: true, motivo: `${n}/${total}` };
58	}
59	
60	export function rodarGuard(caminho, env = process.env) {
61	  // env limpo de GIT_* (hooks do git exportam GIT_DIR/GIT_INDEX_FILE e contaminam repos temporários dos self-tests)
62	  const limpo = Object.fromEntries(Object.entries(env).filter(([k]) => !/^GIT_/i.test(k)));
63	  const r = spawnSync(process.execPath, [caminho, '--self-test'], { encoding: 'utf8', timeout: 600_000, env: { ...limpo, npm_lifecycle_event: '' }, windowsHide: true });
64	  return julgarSaida({ stdout: r.stdout, stderr: r.stderr, status: r.status });
65	}
66	
67	// A lista ESPERADA (issue #17, mutante R1): se a pasta devolver menos do que isto, o runner reprova —
68	// "todos os guards passaram" com zero guards rodados era verde. Dono único: ./guards-esperados.mjs
69	// (importável sem efeito colateral, ao contrário deste runner). Guard novo entra lá no mesmo PR.
70	
71	function guardsDaPasta() {
72	  return readdirSync(AQUI).filter((f) => /^[a-z0-9-]+\.mjs$/.test(f) && !NAO_SAO_GUARDS.includes(f)).sort();
73	}
74	
75	/** Casos do próprio runner (rodam no main — mutante R2 "julgarSaida sempre ok" cai aqui, não só no --self-test). */
76	function casosRunner(check) {
77	  check('runner: linha OK com N>0 → ok', julgarSaida({ stdout: '[x] SELF-TEST OK — 12/12 casos (incl. 3 tentativas de bypass).', status: 0 }).ok === true);
78	  check('runner BYPASS (M17): saída VAZIA com exit 0 → reprova como MUDO', (() => { const r = julgarSaida({ stdout: '', status: 0 }); return r.ok === false && /mudo/i.test(r.motivo); })());
79	  check('runner BYPASS: exit 0 sem a linha → reprova', julgarSaida({ stdout: 'rodou tudo, confia', status: 0 }).ok === false);
80	  check('runner BYPASS: "0/0 casos" → reprova', julgarSaida({ stdout: 'SELF-TEST OK — 0/0 casos', status: 0 }).ok === false);
81	  check('runner BYPASS: linha OK mas exit 1 → reprova', julgarSaida({ stdout: 'SELF-TEST OK — 3/3 casos', status: 1 }).ok === false);
82	  const achados = guardsDaPasta();
83	  const faltam = GUARDS_ESPERADOS.filter((g) => !achados.includes(g));
84	  check(`runner BYPASS (R1): os ${GUARDS_ESPERADOS.length} guards esperados estão na pasta${faltam.length ? ` — faltam: ${faltam.join(', ')}` : ''}`, faltam.length === 0);
85	  check('runner: SELFTESTS_FORA_DE_GUARDS lista reservar-numero.mjs (self-test do comando, fora de scripts/guards, relativo à pasta-mãe)', SELFTESTS_FORA_DE_GUARDS.includes('reservar-numero.mjs'));
86	}
87	
88	// ─── casos da doutrina (as três funções que todo guard usa) ──────────────────
89	function casosDoutrina(check) {
90	  const meuCaminho = fileURLToPath(import.meta.url);
91	  check('doutrina: execução direta é entrypoint', ehEntrypoint(import.meta.url, meuCaminho, (p) => p) === true);
92	  check('doutrina: execução via JUNCTION continua entrypoint (fail-open resolvendo link)', ehEntrypoint(import.meta.url, '/link/atalho.mjs', (p) => (p === '/link/atalho.mjs' ? meuCaminho : p)) === true);
93	  check('doutrina: import de verdade (argv aponta para OUTRO arquivo) não é entrypoint', ehEntrypoint(import.meta.url, `${meuCaminho}.outro`, (p) => p) === false);
94	  check('doutrina: sem argv[1] → RODA (fail-open)', ehEntrypoint(import.meta.url, '', (p) => p) === true);
95	  check('doutrina: URL ilegível → RODA (fail-open)', ehEntrypoint('não-é-url', 'c:/x.mjs', (p) => p) === true);
96	  check('doutrina: mesmoArquivo ignora caixa e barra', mesmoArquivo('C:\\Repo\\G.mjs', 'c:/repo/g.mjs', (p) => p) === true);
97	  const mudo = () => {};
98	  check('doutrina: node direto com --self-test é contra-prova', selfTestPedido(['node', 'g.mjs', '--self-test'], {}, mudo) === true);
99	  check('doutrina: npm run <guard>:selftest é contra-prova', selfTestPedido(['node', 'g.mjs', '--self-test'], { npm_lifecycle_event: 'x:selftest' }, mudo) === true);
100	  check('BYPASS (M18): npm run <guard> -- --self-test NÃO é contra-prova', selfTestPedido(['node', 'g.mjs', '--self-test'], { npm_lifecycle_event: 'prova-colada' }, mudo) === false);
101	  check('doutrina: sem a flag nunca é contra-prova', selfTestPedido(['node', 'g.mjs'], {}, mudo) === false);
102	  const silencio = { log: console.log, error: console.error }; console.log = () => {}; console.error = () => {};
103	  try {
104	    check('BYPASS (M16): relator com 1 falha devolve 1', relatarSelfTest('x', [{ nome: 'a', ok: true }, { nome: 'b', ok: false }]) === 1);
105	    check('doutrina: relator com tudo verde devolve 0', relatarSelfTest('x', [{ nome: 'a', ok: true }]) === 0);
106	  } finally { console.log = silencio.log; console.error = silencio.error; }
107	}
108	
109	function main() {
110	  const casos = [];
111	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
112	  casosDoutrina(check);
113	  casosRunner(check);
114	  const falhas = casos.filter((c) => !c.ok);
115	  for (const c of casos) console.log(`  ${c.ok ? '✓' : '✗'} ${c.nome}`);
116	  if (falhas.length) { console.error(`[${NOME}] ❌ doutrina/runner reprovou ${falhas.length} caso(s) — nenhum guard é confiável com a base quebrada.`); process.exitCode = 1; return; }
117	  console.log(`[${NOME}] doutrina+runner OK — ${casos.length}/${casos.length}\n`);
118	
119	  // Contagem FUNCIONAL (issue #17): sem `ruins++` numa linha à parte — apagar essa linha era o
120	  // mutante que mascarava um guard vermelho. `ruins` deriva do array; não há linha de incremento
121	  // para deletar, e o self-test PORTA abaixo roda o runner contra um guard vermelho para provar.
122	  const resultadosGuards = guardsDaPasta().map((g) => ({ g, r: rodarGuard(join(AQUI, g)) }));
123	  // self-tests de COMANDO fora de scripts/guards/ (ex.: reservar-numero.mjs) — mesma doutrina, resolvidos
124	  // SEMPRE contra a pasta-mãe real (PASTA_MAE), nunca contra o AQUI fake do self-test deste runner.
125	  const resultadosFora = SELFTESTS_FORA_DE_GUARDS.map((rel) => ({ g: rel, r: rodarGuard(join(PASTA_MAE, rel)) }));
126	  const resultados = [...resultadosGuards, ...resultadosFora];
127	  for (const { g, r } of resultados) console.log(`  ${r.ok ? '✅' : '❌'} ${g.padEnd(28)} ${r.motivo}`);
128	  const rodados = resultados.length;
129	  const ruins = resultados.filter((x) => !x.r.ok).length;
130	  const totalEsperado = GUARDS_ESPERADOS.length + SELFTESTS_FORA_DE_GUARDS.length;
131	  if (rodados < totalEsperado) { console.error(`\n[${NOME}] ❌ rodaram ${rodados}; esperados ${totalEsperado} (${GUARDS_ESPERADOS.length} guards + ${SELFTESTS_FORA_DE_GUARDS.length} self-test(s) fora de scripts/guards).`); process.exitCode = 1; return; }
132	  if (ruins) { console.error(`\n[${NOME}] ❌ ${ruins} sem evidência de self-test. Exit 0 sem a linha "SELF-TEST OK — N/N" é guard MUDO, não guard verde.`); process.exitCode = 1; return; }
133	  console.log(`\n[${NOME}] ✅ ${rodados} (guards + self-tests fora de scripts/guards) imprimiram SELF-TEST OK com N > 0.`);
134	  process.exitCode = 0;
135	}
136	
137	function selfTest() {
138	  const casos = [];
139	  const check = (nome, cond) => casos.push({ nome, ok: Boolean(cond) });
140	  casosDoutrina(check);
141	  casosRunner(check);
142	  check('SELF-TEST FALHOU com exit 1 → reprova citando', /FALHOU/.test(julgarSaida({ stderr: '[x] SELF-TEST FALHOU: 1/9', status: 1 }).motivo));
143	  // PORTA do próprio runner (issue #17): como processo, com a pasta de guards VAZIA → tem que reprovar (R1)
144	  const vazio = mkdtempSync(join(tmpdir(), 'rst-vazio-'));
145	  try {
146	    const st = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 120_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: vazio } }).status;
147	    check('PORTA BYPASS (R1): runner com pasta de guards vazia → exit 1', st === 1);
148	  } finally { rmSync(vazio, { recursive: true, force: true }); }
149	  // PORTA: um guard VERMELHO entre os esperados → o runner TEM que sair 1 (mata o mutante que apaga
150	  // `if (!r.ok) ruins++` e a inversão do predicado de contagem — o guard mudo do #17, um nível acima).
151	  const comRed = mkdtempSync(join(tmpdir(), 'rst-red-'));
152	  try {
153	    GUARDS_ESPERADOS.forEach((g, i) => writeFileSync(join(comRed, g), i === 0
154	      ? "console.error('[fake] SELF-TEST FALHOU: 1/2'); process.exit(1);\n"
155	      : "console.log('[fake] SELF-TEST OK — 2/2 casos (incl. 1 tentativas de bypass).'); process.exit(0);\n"));
156	    const st = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 120_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: comRed } }).status;
157	    check('PORTA: 1 guard vermelho entre os esperados → runner exit 1 (não mascara guard mudo)', st === 1);
158	  } finally { rmSync(comRed, { recursive: true, force: true }); }
159	  // PORTA: self-test FORA de scripts/guards (scripts/reservar-numero.mjs, real) roda de verdade e conta
160	  // pro relatório/total — pasta de guards fake toda verde, RAIZ continua sendo a raiz REAL do repo.
161	  const comOk = mkdtempSync(join(tmpdir(), 'rst-ok-'));
162	  try {
163	    GUARDS_ESPERADOS.forEach((g) => writeFileSync(join(comOk, g), "console.log('[ok] SELF-TEST OK — 1/1 casos (incl. 0 tentativas de bypass).'); process.exit(0);\n"));
164	    const r = spawnSync(process.execPath, [fileURLToPath(import.meta.url)], { encoding: 'utf8', timeout: 600_000, env: { ...process.env, npm_lifecycle_event: '', RUN_SELFTESTS_DIR: comOk } });
165	    check(
166	      'PORTA: self-test fora de scripts/guards (scripts/reservar-numero.mjs) roda e aparece no relatório, contribuindo pro exit',
167	      /reservar-numero\.mjs/.test(r.stdout) && r.status === 0,
168	    );
169	  } finally { rmSync(comOk, { recursive: true, force: true }); }
170	  const dir = mkdtempSync(join(tmpdir(), 'rst-'));
171	  try {
172	    const mudo = join(dir, 'mudo.mjs'); writeFileSync(mudo, 'process.exit(0);\n');
173	    const ok = join(dir, 'ok.mjs'); writeFileSync(ok, "console.log('[ok] SELF-TEST OK — 2/2 casos (incl. 1 tentativas de bypass).');\n");
174	    check('guard falso MUDO (exit 0, sem saída) → reprovado pelo runner', rodarGuard(mudo).ok === false);
175	    check('guard falso com a linha → aprovado pelo runner', rodarGuard(ok).ok === true);
176	  } finally { rmSync(dir, { recursive: true, force: true }); }
177	  process.exitCode = relatarSelfTest(NOME, casos);
178	}
179	
180	// SEM portão de entrypoint, de propósito: este runner vigia a doutrina, então não pode depender dela
181	// para decidir se roda — com `ehEntrypoint` mutado para false (M17), o runner ficaria mudo junto
182	// com os guards e o CI sairia verde (medido em 2026-09-10). Ele é CLI por definição; roda sempre.
183	if (selfTestPedido()) selfTest(); else main();
184

