1	#!/usr/bin/env node
2	/**
3	 * ─── INTENÇÃO (certidão de nascimento) ───────────────────────────────────────
4	 * POR QUE EXISTE: teste escrito DEPOIS do conserto nasce verde e nunca provou nada. Na esteira de
5	 *   origem, 28 de 48 companions ficavam verdes com o código de ANTES do fix — "tem teste" era
6	 *   fachada. A pergunta certa não é "o teste passa?", é "o teste ficaria VERMELHO se o conserto
7	 *   não existisse?". Este guard faz a pergunta por máquina.
8	 *
9	 * O QUE FAZ: acha os testes (`*.test.mjs|*.test.js`) e as fontes que o diff contra a base toca;
10	 *   cria uma worktree descartável NA BASE, copia para lá a versão HEAD dos testes tocados, roda
11	 *   `node --test` neles (esperado: FALHA — o teste morde a base); depois roda os mesmos testes no
12	 *   HEAD (esperado: PASSA). Só `PROVOU_O_FIX` sai 0.
13	 *
14	 * O QUE NUNCA MAIS PODE PASSAR:
15	 *   1. teste que passa na base (`NAO_MORDE_A_BASE`) — não distingue antes de depois;
16	 *   2. teste que falha no HEAD (`VERMELHO_NO_HEAD`) — o conserto não está pronto;
17	 *   3. "não consegui montar a réplica" saindo como 0 — é exit 2 (NÃO MEDIU).
18	 *
19	 * LIMITE CONHECIDO: (a) só julga quando o diff tem teste E fonte — diff só de doc/config sai
20	 *   `NAO_APLICAVEL` (0); a existência do teste do item 4 do PLANO é do `plano-na-issue` e do
21	 *   auditor; (b) roda `node --test` — projeto com outro runner declara `--cmd "<comando>"`;
22	 *   (c) não sabe se o teste exercita a fonte alterada (pode morder por outro motivo) — o auditor
23	 *   confere no passo 4; (d) Windows trava pasta com cwd dentro: a réplica é removida com --force e
24	 *   o resto fica para o varredor; (e) CÓDIGO PYTHON (R6, 2026-09-11) — em projeto com "stack":"python"
25	 *   em esteira.json, reconhece teste Python (convenção de lib/python-test.mjs) e roda
26	 *   `<python> -m pytest -q <arquivo>` (resolução de lib/python-runtime.mjs); `--cmd` explícito continua
27	 *   tendo prioridade sobre qualquer stack. Python/pytest AUSENTE nunca vira verde por omissão: o estado
28	 *   `FERRAMENTA_AUSENTE` sai NÃO MEDIU (exit 2) com a dica de instalação — nunca 0/1 sem a ferramenta real.
29	 *
30	 * CONTRA-PROVA: `node guards/companion-red-green.mjs --self-test` — monta um repo temporário real
31	 *   com fonte quebrada → conserto + teste, e prova PROVOU_O_FIX; depois um teste que passa na base
32	 *   e prova NAO_MORDE_A_BASE; e um teste quebrado no HEAD → VERMELHO_NO_HEAD.
33	 * ─────────────────────────────────────────────────────────────────────────────
34	 */
35	import { execFileSync, spawnSync } from 'node:child_process';
36	import { existsSync, mkdtempSync, rmSync, mkdirSync, copyFileSync, writeFileSync } from 'node:fs';
37	import { join, dirname, resolve } from 'node:path';
38	import { tmpdir } from 'node:os';
39	import { fileURLToPath } from 'node:url';
40	import { ehEntrypoint, selfTestPedido, relatarSelfTest } from '../lib/guard-doctrine.mjs';
41	import { stackDoProjeto } from '../lib/stack.mjs';
42	import { resolverPython } from '../lib/python-runtime.mjs';
43	import { RE_TESTE_PY, RE_FONTE_PY } from '../lib/python-test.mjs';
44	
45	const NOME = 'companion-red-green';
46	export const R = Object.freeze({
47	  PROVOU_O_FIX: 'PROVOU_O_FIX', NAO_MORDE_A_BASE: 'NAO_MORDE_A_BASE', VERMELHO_NO_HEAD: 'VERMELHO_NO_HEAD',
48	  NAO_APLICAVEL: 'NAO_APLICAVEL',
49	  // R6 (2026-09-11): python sem ruff/pytest instalado — NÃO MEDIU explícito, NUNCA verde por ferramenta ausente.
50	  FERRAMENTA_AUSENTE: 'FERRAMENTA_AUSENTE',
51	});
52	const RE_TESTE = /\.(test|spec)\.(mjs|cjs|js|ts)$/i;
53	const RE_FONTE = /\.(mjs|cjs|js|ts|tsx|jsx|mts|cts)$/i;
54	
55	// Dentro de um hook do git (pre-commit), o git exporta GIT_DIR/GIT_INDEX_FILE/GIT_PREFIX para os filhos —
56	// e o repo TEMPORÁRIO do self-test passa a operar no repo do hook (medido em 2026-09-10: self-test
