143	export const NOME = 'import-boundaries';
144	const MARCADOR_OPTOUT = 'fronteira-de-proposito';
145	const MAX_RETROCESSO_STATEMENT = 20; // linhas pra trás procurando o início de um `import {...} from` multi-linha (IB-8)
146	
147	/** Acha a linha (1-based) onde COMEÇA o statement de import que contém `linhaAlvo` — só usado pro opt-out
148	 *  multi-linha (IB-8): volta a partir de `linhaAlvo` até achar, no texto DESPIDO (sem string/comentário),
149	 *  uma linha que comece com `import`/`export`. Não achou dentro da janela → devolve a própria `linhaAlvo`
150	 *  (span de 1 linha, o comportamento de antes). Puro: só olha `linhasDesp`, não lê fs. */
151	function inicioDoStatement(linhasDesp, linhaAlvo) {
152	  for (let l = linhaAlvo; l >= Math.max(1, linhaAlvo - MAX_RETROCESSO_STATEMENT); l--) {
153	    if (/^\s*(?:import|export)\b/.test(linhasDesp[l - 1] || '')) return l;
154	  }
155	  return linhaAlvo;
156	}
