158	/** O opt-out é válido no `trecho` (texto ORIGINAL, 1+ linhas)? Extrai só o que está DENTRO de comentário
159	 *  (`//…` até o fim da linha, `/*…*\/` mesmo cruzando linha dentro do trecho) e exige
160	 *  `fronteira-de-proposito: <motivo não-vazio>` ali dentro — marcador em string ou sem `: motivo` não conta
161	 *  (decisão do coordenador #2; IB-7 marcador-fora-do-trecho, IB-8 motivo/comentário). */
162	function optOutValido(trecho) {
163	  const partes = [];
164	  const re = /\/\/(.*)$|\/\*([\s\S]*?)\*\//gm;
165	  let m;
166	  while ((m = re.exec(trecho))) partes.push(m[1] ?? m[2] ?? '');
167	  const comentario = partes.join('\n');
168	  const mm = comentario.match(new RegExp(`${MARCADOR_OPTOUT}\\s*:\\s*(\\S.*)`));
169	  return Boolean(mm && mm[1] && mm[1].trim().length > 0);
170	}
