244	/** FUNÇÃO PURA (IB-4): a FORMA de `.arch-layers.json` dá pra medir alguma coisa? Não julga o CONTEÚDO
245	 *  (se os globs fazem sentido é decisão humana, item (d) de "O QUE NÃO VÊ") — só a FORMA: chave errada,
246	 *  `{}`, `[]`, `null`, camada sem `globs` (array de string não-vazio), ou glob com `\` (Windows: nunca casa
247	 *  um caminho relativo, que sempre usa "/"). Devolve o MOTIVO (string) se inválida, `null` se válida —
248	 *  decisão do coordenador: config que não mede nada é NÃO MEDIU, nunca ✅ (GUARDS_PARALELO.md §7.1). */
249	export function validarFormaConfig(cfg) {
250	  if (cfg === null) return 'o arquivo existe mas o conteúdo é JSON "null" — sem config, não há o que medir';
251	  if (typeof cfg !== 'object' || Array.isArray(cfg)) return '.arch-layers.json não é um objeto JSON';
252	  const camadas = cfg.camadas;
253	  if (typeof camadas !== 'object' || camadas === null || Array.isArray(camadas) || Object.keys(camadas).length === 0) {
254	    return 'chave "camadas" ausente, vazia ou com nome errado (confira: é "camadas", não "camada"?)';
255	  }
256	  for (const [nome, c] of Object.entries(camadas)) {
257	    if (typeof c !== 'object' || c === null) return `camada "${nome}" não é um objeto`;
258	    if (!Array.isArray(c.globs) || c.globs.length === 0 || !c.globs.every((g) => typeof g === 'string' && g.length > 0)) {
259	      return `camada "${nome}".globs precisa ser um array de string(s) não-vazio`;
260	    }
261	    const comBarra = c.globs.find((g) => g.includes('\\'));
262	    if (comBarra) return `camada "${nome}" tem glob com "\\" (use "/"): "${comBarra}" nunca casa um caminho real`;
263	    if (c.podeImportar !== undefined && !Array.isArray(c.podeImportar)) return `camada "${nome}".podeImportar precisa ser um array`;
264	  }
265	  return null;
266	}
