268	function explicacao(a) {
269	  if (a.tipo === 'camada-proibida') {
270	    return `camada "${a.camadaOrigem}" não pode importar a camada "${a.camadaAlvo}" (${a.ofensor}) — acrescente`
271	      + ` "${a.camadaAlvo}" ao podeImportar de "${a.camadaOrigem}" se for decisão nova, ou remova o import`;
272	  }
