286	/** Lê os arquivos de `dir` e devolve `{ achados, naoResolvidos }` (fs; não é a função pura — a função pura
287	 *  é julgarArquivo). `naoResolvidos` são os imports relativos que não bateram em arquivo real — não é
288	 *  achado (BANCA: NULO), mas é CONTADO e reportado: nunca descartado em silêncio (IB-1). */
289	function escanear(dir, cfg) {
