291	  const naoResolvidos = [];
292	  const resolver = (esp, de) => resolverImport(esp, de, dir);
293	  for (const caminho of listarCodigo(dir, { ignorar: cfg.ignorar || [] })) {
294	    let fonte;
295	    try { fonte = readFileSync(join(dir, caminho), 'utf8'); } catch { continue; }
296	    for (const a of julgarArquivo({ caminho, fonte, cfg, resolver })) achados.push({ arquivo: caminho, ...a });
297	    if (arquivoForaDeCamada(caminho, cfg)) achados.push({ arquivo: caminho, tipo: 'fora-de-camada', linha: 1 });
