123	 * FUNÇÃO PURA: audita o texto (já com imports resolvidos, já despido de comentário/bloco/span) contra a
124	 * Bússola. Sem fs, sem exit. Estrutural — não decide o que "conta" como texto real (isso é
125	 * `despirMarkdown`, chamado por `auditarBussola`).
126	 * @param {string} texto
127	 * @returns {{ok: boolean, problemas: string[]}}
128	 */
129	export function auditarLeis(texto) {
130	  const linhas = String(texto ?? '').split('\n');
131	
132	  const idxSecoes = [];
133	  linhas.forEach((l, i) => { if (RE_SECAO.test(l)) idxSecoes.push(i); });
134	
135	  if (idxSecoes.length === 0) {
136	    return { ok: false, problemas: ['secao-ausente — não achei a seção "## AS 12 LEIS DO DESENVOLVIMENTO".'] };
137	  }
138	  if (idxSecoes.length > 1) {
139	    return { ok: false, problemas: [`secao-duplicada — a seção aparece ${idxSecoes.length}x (esperado 1x).`] };
140	  }
141	
142	  const inicio = idxSecoes[0] + 1;
143	  let fim = linhas.length;
144	  for (let i = inicio; i < linhas.length; i++) { if (RE_FIM_SECAO.test(linhas[i])) { fim = i; break; } }
145	
146	  const itens = [];
147	  for (const l of linhas.slice(inicio, fim)) {
148	    const m = l.match(RE_ITEM);
149	    if (m) itens.push({ numero: Number(m[1]), nome: normalizar(m[2]) });
150	  }
151	
152	  const problemas = [];
153	  if (itens.length !== 12) {
154	    problemas.push(`contagem — achou ${itens.length} leis numeradas de topo (esperado 12).`);
155	  }
156	
157	  const n = Math.min(itens.length, NOMES_CANONICOS_NORM.length);
158	  for (let i = 0; i < n; i++) {
159	    const posicao = i + 1;
160	    if (itens[i].numero !== posicao) {
161	      problemas.push(`numeracao — posição ${posicao} tem número ${itens[i].numero} (esperado ${posicao}).`);
162	    }
163	    if (itens[i].nome !== NOMES_CANONICOS_NORM[i]) {
164	      problemas.push(`nome — posição ${posicao}: esperado "${NOMES_CANONICOS[i]}", achou "${itens[i].nome}".`);
165	    }
166	  }
167	
168	  return { ok: problemas.length === 0, problemas };
169	}
