171	/**
172	 * FUNÇÃO PURA: auditarLeis, mas primeiro remove comentário HTML/bloco de código cercado/code span
173	 * (`despirMarkdown`) — é isso que o Claude Code NÃO injeta no contexto (LI-1, LI-7). Esta é a função
174	 * usada por `principal()`; `auditarLeis` continua exportada e testada isoladamente (o núcleo estrutural).
175	 * @param {string} textoBruto
176	 * @returns {{ok: boolean, problemas: string[]}}
177	 */
178	export function auditarBussola(textoBruto) {
179	  return auditarLeis(despirMarkdown(textoBruto));
180	}
