182	/**
183	 * FUNÇÃO PURA: acha toda ocorrência de "@<especificador>" no texto, em QUALQUER posição da linha (não
184	 * só sozinha numa linha — LI-4/B1), IGNORANDO ocorrências dentro de comentário HTML, bloco de código
185	 * cercado ou code span (via `despirMarkdown` — mesmo comprimento, os índices batem com o ORIGINAL, já
186	 * que fora dessas regiões o texto "limpo" é idêntico ao bruto). Sem fs, sem exit.
187	 * @param {string} texto
188	 * @returns {{especificador: string, indice: number, comprimento: number}[]} na ordem em que aparecem
189	 */
190	export function acharImportsEmTexto(texto) {
191	  const bruto = String(texto ?? '');
192	  const limpo = despirMarkdown(bruto);
193	  const resultados = [];
194	  const RE = /@(\S+)/g;
195	  let m;
196	  while ((m = RE.exec(limpo)) !== null) {
197	    resultados.push({ especificador: m[1], indice: m.index, comprimento: m[0].length });
198	  }
199	  return resultados;
200	}
201	
202	/** BOM (U+FEFF) inicial removido — não é `\n`, não desloca a contagem de linha (LI-8). */
203	function removerBOM(s) {
204	  const t = String(s ?? '');
205	  return t.charCodeAt(0) === 0xFEFF ? t.slice(1) : t;
206	}
207	
208	/**
209	 * Resolve `@imports` RECURSIVAMENTE (até MAX_HOPS), em qualquer posição da linha, fora de
210	 * comentário/bloco cercado/code span. Espelha a sintaxe real do Claude Code: caminho ABSOLUTO é usado
211	 * como está; `~/` vira homedir; caminho RELATIVO resolve a partir do ARQUIVO que importa (não sempre da
212	 * raiz — LI-4/B6). Import que não existe (typo, menção tipo "@fulano") NÃO quebra sozinho: fica literal
213	 * no texto — o efeito real, se ele carregava a seção, aparece como `secao-ausente` na auditoria final,
214	 * igual ao Claude Code de verdade ("the imports stay disabled") — LI-4/B5. Import cujo alvo resolvido
215	 * CAI FORA de `dirRaiz` é bloqueado — devolvido em `foraDoRepo`, curto-circuitando a recursão (LI-3/C2).
216	 * `existe`/`ler`/`homedir` injetáveis (Parte 3 da doutrina) — o self-test roda a maior parte disto
217	 * OFFLINE, sem tocar o disco real.
218	 * @param {string} texto
219	 * @param {string} dirRaiz
220	 * @param {{existe?: (p:string)=>boolean, ler?: (p:string)=>string, homedir?: () => string}} [deps]
221	 * @returns {{texto: string|null, foraDoRepo: {especificador:string, alvo:string}|null, naoResolvidos: string[]}}
222	 */
223	export function resolverImportsRecursivo(texto, dirRaiz, deps = {}) {
224	  const existe = deps.existe || existsSync;
225	  const ler = deps.ler || ((p) => readFileSync(p, 'utf8'));
226	  const pegarHomedir = deps.homedir || osHomedir;
227	  const naoResolvidos = [];
228	
229	  function expandir(txt, baseDir, hop, visitados) {
230	    const imports = acharImportsEmTexto(txt);
231	    if (imports.length === 0) return { texto: txt, foraDoRepo: null };
232	    let out = txt;
233	    // da direita pra esquerda: substituir não bagunça o índice dos imports ainda não processados
234	    for (let k = imports.length - 1; k >= 0; k--) {
235	      const { especificador, indice, comprimento } = imports[k];
236	      let alvo;
237	      if (especificador.startsWith('~/')) alvo = join(pegarHomedir(), especificador.slice(2));
238	      else if (isAbsolute(especificador)) alvo = especificador;
239	      else alvo = join(baseDir, especificador);
240	
241	      const rel = relative(dirRaiz, alvo);
242	      if (rel.startsWith('..') || isAbsolute(rel)) {
243	        return { texto: null, foraDoRepo: { especificador, alvo } };
244	      }
245	      if (hop > MAX_HOPS || visitados.has(alvo) || !existe(alvo)) {
246	        naoResolvidos.push(especificador); // não expande: fica literal — não quebra sozinho (LI-4/B5)
247	        continue;
248	      }
249	      const conteudo = removerBOM(ler(alvo));
250	      const sub = expandir(conteudo, dirname(alvo), hop + 1, new Set(visitados).add(alvo));
251	      if (sub.foraDoRepo) return sub;
252	      // Import no MEIO de uma linha (LI-4/B1: "As leis estão em @leis.md — leia..."): colar o conteúdo
253	      // importado char-a-char quebraria o "^##" do título dele (deixaria de estar no INÍCIO da linha).
254	      // Envolve o bloco importado em quebra de linha própria quando ele não já começa/termina numa —
255	      // o texto que vem antes/depois na MESMA linha vira sua própria linha, o importado vira as dele.
256	      const antes = out.slice(0, indice);
257	      const depois = out.slice(indice + comprimento);
258	      const precisaQuebraAntes = antes.length > 0 && !antes.endsWith('\n');
259	      const precisaQuebraDepois = depois.length > 0 && !depois.startsWith('\n');
260	      const bloco = (precisaQuebraAntes ? '\n' : '') + sub.texto + (precisaQuebraDepois ? '\n' : '');
261	      out = antes + bloco + depois;
262	    }
263	    return { texto: out, foraDoRepo: null };
264	  }
265	
266	  const resultado = expandir(String(texto ?? ''), dirRaiz, 1, new Set());
267	  return { ...resultado, naoResolvidos };
268	}
