270	/**
271	 * Localiza a Bússola nos dois locais oficiais do Claude Code (LI-2): `<dir>/CLAUDE.md` e
272	 * `<dir>/.claude/CLAUDE.md`. Nenhum → `caminhos: []`. Um só → esse. Os dois → concatenados (raiz
273	 * primeiro) — se os dois trouxerem a seção completa, isso é `secao-duplicada`, corretamente. BOM
274	 * removido de CADA arquivo (LI-8).
275	 */
276	function localizarBussola(dir) {
277	  const caminhoRaiz = join(dir, ARQUIVO_ALVO);
278	  const caminhoOculto = join(dir, '.claude', ARQUIVO_ALVO);
279	  const temRaiz = existsSync(caminhoRaiz);
280	  const temOculto = existsSync(caminhoOculto);
281	  const caminhos = [];
282	  const partes = [];
283	  if (temRaiz) { partes.push(removerBOM(readFileSync(caminhoRaiz, 'utf8'))); caminhos.push(caminhoRaiz); }
284	  if (temOculto) { partes.push(removerBOM(readFileSync(caminhoOculto, 'utf8'))); caminhos.push(caminhoOculto); }
285	  return { caminhos, bruto: caminhos.length ? partes.join('\n') : null };
286	}
