288	export function principal({ argv = process.argv.slice(2), cwd = process.cwd() } = {}) {
289	  const i = argv.indexOf('--dir');
290	  if (i >= 0 && !argv[i + 1]) { console.error(`[${NOME}] NÃO MEDIU: --dir sem caminho.`); return 2; }
291	  const dir = i >= 0 ? argv[i + 1] : cwd;
292	
293	  // LI-5: --dir apontando pra pasta que NÃO EXISTE (ou não é pasta) é entrada errada, não "sem CLAUDE.md".
294	  if (!existsSync(dir) || !statSync(dir).isDirectory()) {
295	    console.error(`[${NOME}] NÃO MEDIU: --dir "${dir}" não existe (ou não é uma pasta) — confira o caminho (typo, cwd errado no CI, template movido).`);
296	    return 2;
297	  }
298	
299	  const { caminhos, bruto } = localizarBussola(dir);
300	  if (caminhos.length === 0) {
301	    console.log(`[${NOME}] ✅ NÃO SE APLICA: ${dir} não tem ${ARQUIVO_ALVO} (nem em .claude/${ARQUIVO_ALVO}).`);
302	    return 0;
303	  }
304	
305	  const { texto, foraDoRepo, naoResolvidos } = resolverImportsRecursivo(bruto, dir);
306	  if (foraDoRepo) {
307	    console.error(`[${NOME}] FALHA: import-fora-do-repo — "@${foraDoRepo.especificador}" resolve para ${foraDoRepo.alvo}, fora de ${dir}.`);
308	    console.error(
309	      `[${NOME}] COMO PASSAR: a Bússola não pode depender de um arquivo fora do projeto — traga o ` +
310	      `conteúdo pra dentro de ${dir} ou remova o import.`,
311	    );
312	    console.error(
313	      `[${NOME}] POR QUE EXISTE: um import externo pode não estar disponível (aprovação recusada, ` +
314	      `caminho de outra máquina) — a bússola não pode depender de algo fora do repo.`,
315	    );
316	    return 1;
317	  }
318	
319	  const veredito = auditarLeis(despirMarkdown(texto));
320	  if (veredito.ok) {
321	    console.log(`[${NOME}] ✅ as 12 leis estão íntegras em ${caminhos.join(' + ')}.`);
322	    return 0;
323	  }
324	  for (const p of veredito.problemas) console.error(`[${NOME}] FALHA: ${p}`);
325	  if (naoResolvidos.length) {
326	    console.error(`[${NOME}] NOTA: também não resolvi estas referências "@..." (podem ser menções, não imports): ${[...new Set(naoResolvidos)].join(', ')}`);
327	  }
328	  console.error(
329	    `[${NOME}] COMO PASSAR: restaure a seção "## AS 12 LEIS DO DESENVOLVIMENTO" com as 12 leis ` +
330	    `canônicas, na ordem 1..12, com o nome em negrito exatamente igual ao de templates/CLAUDE.md — ` +
331	    `fora de comentário HTML, bloco de código cercado ou code span.`,
332	  );
333	  console.error(
334	    `[${NOME}] POR QUE EXISTE: a Bússola é a única fonte de verdade do método — se o texto for ` +
335	    `editado em silêncio (lei sumida/trocada/renomeada/escondida em comentário), toda sessão nova ` +
336	    `passa a segui-la errada sem ninguém perceber.`,
337	  );
338	  return 1;
339	}
340	
341	if (ehEntrypoint(import.meta.url)) {
342	  if (selfTestPedido()) {
343	    // SEM `await` no topo do módulo de propósito: o companheiro importa este arquivo de volta
344	    // (`../leis-integrity.mjs`, ciclo estático) — `await` aqui deixaria ESTE módulo "evaluating-async"
345	    // enquanto o companheiro tenta reimportá-lo, um deadlock real do linker de ESM. Sem `await`, este
346	    // módulo termina de avaliar (síncrono) antes do import() assentar — quebra o ciclo, mesmo
347	    // comportamento (Node segura o processo vivo até a Promise resolver).
348	    import('./selftest/leis-integrity.mjs').then(({ selfTest }) => {
349	      process.exitCode = selfTest();
350	    });
351	  } else {
352	    try {
353	      process.exitCode = principal();
354	    } catch (e) {
355	      console.error(`[${NOME}] NÃO MEDIU: ${e?.message || e}`);
356	      process.exitCode = 2;
357	    }
358	  }
359	}
