1	/**
2	 * guard-doctrine.mjs — as perguntas que todo guard do kit faz antes de rodar.
3	 * Portado da esteira de origem; só as funções que os guards do kit usam.
4	 *
5	 * REGRA: na dúvida, RODA. Guard que roda a mais custa um commit lento; guard que não roda custa um
6	 * incidente. Por isso `ehEntrypoint` é fail-OPEN e resolve junction/symlink (o Windows executa
7	 * arquivo por junction e a comparação de string de caminho dizia "não sou eu" — guard mudo).
8	 */
9	import { realpathSync } from 'node:fs';
10	import { fileURLToPath } from 'node:url';
11	
12	export function mesmoArquivo(a, b, resolver = realpathSync) {
13	  if (!a || !b) return false;
14	  const norm = (p) => {
15	    let r;
16	    try { r = resolver(p); } catch { r = p; }
17	    return String(r).replaceAll('\\', '/').replace(/\/+$/, '').toLowerCase();
18	  };
19	  return norm(a) === norm(b);
20	}
