33	 * medido). Honra a flag só em `node <arquivo> --self-test` ou `npm run <guard>:selftest`.
34	 */
35	export function selfTestPedido(argv = process.argv, env = process.env, avisar = console.error) {
36	  if (!argv.includes('--self-test')) return false;
37	  const evento = String(env.npm_lifecycle_event || '');
38	  if (!evento) return true;
