46	  for (const c of casos) console.log(`  ${c.ok ? '✓' : '✗'} ${c.nome}`);
47	  const falhas = casos.filter((c) => !c.ok);
48	  if (falhas.length) { console.error(`[${nome}] SELF-TEST FALHOU: ${falhas.length}/${casos.length}`); return 1; }
49	  const bypasses = casos.filter((c) => c.nome.startsWith('BYPASS')).length;
50	  console.log(`[${nome}] SELF-TEST OK — ${casos.length}/${casos.length} casos (incl. ${bypasses} tentativas de bypass).`);
