66	/** "AAAAMMDDhhmmss" a partir de uma Date, em UTC (RN-09: hora local já causou timestamp errado). */
67	export function timestampAtual(d = new Date()) {
68	  const p = (n) => String(n).padStart(2, '0');
69	  return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}${p(d.getUTCHours())}`
