75	  const s = String(numeroOuTexto ?? '').padStart(14, '0').slice(-14);
76	  const n = (i, j) => Number(s.slice(i, j));
77	  return new Date(Date.UTC(n(0, 4), n(4, 6) - 1, n(6, 8), n(8, 10), n(10, 12), n(12, 14)));
