105	/** timestamp livre: PISO no maior número existente + 1s (RN-09 — nunca menor que isso, mesmo se "agora"
106	 *  for anterior a um timestamp futuro já reservado), depois avança 1s enquanto `numeroExiste` ocupado. */
107	export function proximoNumeroTimestamp(sets, agora = new Date()) {
108	  const maior = maiorNumero(sets);
109	  let d = agora;
110	  if (maior > 0) {
111	    const piso = new Date(dataDoTimestamp(maior).getTime() + 1000);
112	    if (piso.getTime() > d.getTime()) d = piso;
113	  }
114	  let cand = timestampAtual(d);
115	  let guarda = 0;
116	  while (numeroExiste(Number(cand), sets) && guarda < 3600) {
117	    d = new Date(d.getTime() + 1000);
118	    cand = timestampAtual(d);
119	    guarda++;
120	  }
121	  return cand;
