161	/** parseia o frontmatter de uma reserva: aceita BOM (editor Windows — RN-07) e valor entre aspas simples
162	 *  ou duplas (YAML válido — RN-07); null se não achar o bloco `---...---`. */
163	export function parseFrontmatterReserva(texto) {
164	  const semBom = String(texto ?? '').replace(new RegExp('^\uFEFF'), '');
165	  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(semBom);
166	  if (!m) return null;
167	  const obj = {};
168	  for (const linhaBruta of m[1].split('\n')) {
169	    const linha = linhaBruta.replace(/\r$/, '');
170	    const i = linha.indexOf(':');
171	    if (i < 0) continue;
172	    const chave = linha.slice(0, i).trim();
173	    let valor = linha.slice(i + 1).trim();
174	    const aspas = /^"([\s\S]*)"$/.exec(valor) || /^'([\s\S]*)'$/.exec(valor);
175	    if (aspas) valor = aspas[1];
176	    obj[chave] = valor;
177	  }
178	  return obj;
179	}
