207	 */
208	export function listarItensNumerados(dirAbs, { pularCaminhos = new Set(), ehOutroCheckout = () => false } = {}) {
209	  const itens = [];
210	  const naoMedidos = [];
211	  const pilha = [dirAbs];
212	  while (pilha.length) {
213	    const atual = pilha.pop();
214	    let entradas;
215	    try {
216	      entradas = readdirSync(atual, { withFileTypes: true });
217	    } catch (e) {
218	      if (atual === dirAbs) throw e;
219	      continue; // subpasta que sumiu no meio da varredura: pulada em silêncio, como sempre
220	    }
221	    for (const ent of entradas) {
222	      if (ent.name === 'node_modules' || ent.name === '.git') continue;
223	      const p = join(atual, ent.name);
224	      if (pularCaminhos.has(resolve(p))) continue;
225	      if (ent.isSymbolicLink()) { naoMedidos.push({ caminho: p, motivo: 'junction/symlink' }); continue; }
226	      const m = RE_NOME_NUMERADO.exec(ent.name);
227	      if (m) { itens.push({ caminhoAbs: p, nome: ent.name, numero: m[1], slug: m[2], isDir: ent.isDirectory() }); continue; }
228	      if (ent.isDirectory() && !ehOutroCheckout(p)) pilha.push(p);
229	    }
230	  }
231	  return { itens, naoMedidos };
232	}
