236	 * de `node_modules`, `.git`, `referencia/` e outro checkout git DE VERDADE (RN-05/06: "toda pasta
237	 * `migrations` achada em qualquer nível"). Uma pasta achada é FOLHA (não desce dentro pra achar outra
238	 * com o mesmo nome aninhada — caso degenerado, não é o que os achados pedem). Symlink/junction não é
239	 * seguido (evita ciclo; a mina de junction é do walker de item numerado, não deste). Raiz ilegível LANÇA.
240	 */
241	export function buscarPastasComNome(rootAbs, nomeAlvo, { ehOutroCheckout = () => false } = {}) {
242	  const PULAR = new Set(['node_modules', '.git', 'referencia', '.venv', 'venv', '.uv', '__pycache__', 'site-packages']);
243	  const achadas = [];
244	  const pilha = [rootAbs];
245	  while (pilha.length) {
246	    const atual = pilha.pop();
247	    let entradas;
248	    try {
249	      entradas = readdirSync(atual, { withFileTypes: true });
250	    } catch (e) {
251	      if (atual === rootAbs) throw e;
252	      continue;
253	    }
254	    for (const ent of entradas) {
255	      if (!ent.isDirectory() || ent.isSymbolicLink()) continue;
256	      if (PULAR.has(ent.name)) continue;
257	      const p = join(atual, ent.name);
258	      if (ehOutroCheckout(p)) continue;
259	      if (ent.name === nomeAlvo) { achadas.push(p); continue; }
260	      pilha.push(p);
261	    }
262	  }
263	  return achadas;
264	}
